import{_ as t,o as i,c as s,a2 as n}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Tableau Maître de la Division des Ères","description":"","frontmatter":{},"headers":[],"relativePath":"fr/70-纪元划分总表.md","filePath":"fr/70-纪元划分总表.md"}'),d={name:"fr/70-纪元划分总表.md"};function r(a,e,l,o,u,c){return i(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="tableau-maitre-de-la-division-des-eres" tabindex="-1">Tableau Maître de la Division des Ères <a class="header-anchor" href="#tableau-maitre-de-la-division-des-eres" aria-label="Permalink to &quot;Tableau Maître de la Division des Ères&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>70</td></tr><tr><td>Module</td><td>Ères historiques et grands événements</td></tr><tr><td>Mots clés</td><td>Division des ères, périodisation historique, ascension en quatre étapes, chronologie, jalons</td></tr></tbody></table><h2 id="i-les-principes-fondamentaux-de-la-division-des-eres" tabindex="-1">I. Les Principes Fondamentaux de la Division des Ères <a class="header-anchor" href="#i-les-principes-fondamentaux-de-la-division-des-eres" aria-label="Permalink to &quot;I. Les Principes Fondamentaux de la Division des Ères&quot;">​</a></h2><p>La division des ères historiques de l&#39;Univers Hengyuan prend le chemin d&#39;ascension en quatre étapes comme cadre fondamental, avec l&#39;état de développement du mécanisme de l&#39;Ancre comme base centrale de périodisation. Chaque ère correspond à une transformation fondamentale de la relation entre la civilisation et l&#39;univers ; les frontières entre les ères ne sont pas des points temporels arbitraires, mais sont marquées par des événements majeurs d&#39;importance universelle.</p><p>La division des ères suit trois principes :</p><ul><li><strong>Le principe de correspondance à l&#39;ascension</strong> : chaque grande ère correspond à une étape du chemin d&#39;ascension en quatre étapes, tandis que les sous-périodes au sein d&#39;une ère correspondent aux progrès clés de cette étape.</li><li><strong>Le principe du marquage par les événements</strong> : les points de départ et de fin d&#39;une ère sont déterminés par des événements majeurs emblématiques, plutôt que par de simples divisions égales du temps.</li><li><strong>Le principe de l&#39;état de la civilisation</strong> : chaque ère est nommée d&#39;après les caractéristiques centrales de la civilisation de cette période, reflétant les contradictions principales et la direction de développement du moment.</li></ul><h2 id="ii-le-tableau-maitre-des-eres-historiques-de-l-univers-hengyuan" tabindex="-1">II. Le Tableau Maître des Ères Historiques de l&#39;Univers Hengyuan <a class="header-anchor" href="#ii-le-tableau-maitre-des-eres-historiques-de-l-univers-hengyuan" aria-label="Permalink to &quot;II. Le Tableau Maître des Ères Historiques de l&#39;Univers Hengyuan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>N° d&#39;ère</th><th>Nom de l&#39;ère</th><th>Étape d&#39;ascension correspondante</th><th>Événements marquants des frontières</th><th>Caractéristiques centrales</th></tr></thead><tbody><tr><td>Première ère</td><td>Ère Pré-Ancre</td><td>Pré-ascension</td><td>Naissance de l&#39;univers → éveil de la première génération d&#39;Ancres</td><td>Culture prédatrice dominante, ruptures de civilisation fréquentes</td></tr><tr><td>Deuxième ère</td><td>Ère de l&#39;Éveil de l&#39;Ancre</td><td>Lancement de la fondation de la réalité</td><td>Éveil des Ancres de première génération → signature de la Charte Symbiotique</td><td>Mécanisme de l&#39;Ancre établi, germination de la pensée antiprédation</td></tr><tr><td>Troisième ère</td><td>Période d&#39;Établissement du Système Symbiotique</td><td>Fondation de la réalité</td><td>Signature de la Charte Symbiotique → ouverture complète des Trois Cents Systèmes</td><td>Institutions symbiotiques mises en œuvre, reconstruction sociale achevée</td></tr><tr><td>Quatrième ère</td><td>Ère de l&#39;Ouverture et de l&#39;Activation des Systèmes</td><td>Lancement de l&#39;habilitation technologique</td><td>Ouverture des Trois Cents Systèmes → achèvement de la Stratégie d&#39;Activation de 20 %</td><td>Culture vulgarisée, percées de l&#39;ingénierie des lois</td></tr><tr><td>Cinquième ère</td><td>Ère de la Première Ascension</td><td>Habilitation technologique → évolution de la conscience</td><td>Succès de la première ascension → fondation de la République des Dix Mille Races</td><td>Ascension de la civilisation vérifiée, percée de l&#39;interface du domaine de la conscience</td></tr><tr><td>Sixième ère</td><td>Ère de la République des Dix Mille Races</td><td>Évolution de la conscience</td><td>Fondation de la République des Dix Mille Races → lancement de l&#39;exploration interplans</td><td>Unification des institutions des races, symbiose de la conscience collective</td></tr><tr><td>Septième ère</td><td>Ère de l&#39;Exploration Interplans</td><td>Évolution de la conscience → symbiose interstellaire</td><td>Lancement de l&#39;exploration interplans → achèvement préliminaire du réseau interstellaire</td><td>Grandes découvertes de plans, expansion du réseau de l&#39;Ancre</td></tr><tr><td>Huitième ère</td><td>Ère de la Symbiose Interstellaire</td><td>Symbiose interstellaire</td><td>Achèvement du réseau interstellaire → ascension globale de l&#39;univers</td><td>Symbiose universelle des races, ascension de l&#39;univers en cours</td></tr></tbody></table><h2 id="iii-durees-et-indicateurs-cles-de-chaque-ere" tabindex="-1">III. Durées et Indicateurs Clés de Chaque Ère <a class="header-anchor" href="#iii-durees-et-indicateurs-cles-de-chaque-ere" aria-label="Permalink to &quot;III. Durées et Indicateurs Clés de Chaque Ère&quot;">​</a></h2><p>Étant donné que l&#39;Univers Hengyuan contient plusieurs plans, le flux du temps diffère entre les plans ; les durées des ères sont basées sur le temps standard du plan principal :</p><table tabindex="0"><thead><tr><th>Ère</th><th>Durée estimée</th><th>Couverture de l&#39;Ancre</th><th>Proportion de cultivateurs</th><th>Indice de Symbiose</th></tr></thead><tbody><tr><td>Ère Pré-Ancre</td><td>Inconnaissable (ordre de plusieurs milliards d&#39;années)</td><td>0 %</td><td>&lt;0,01 %</td><td>&lt;10</td></tr><tr><td>Ère de l&#39;Éveil de l&#39;Ancre</td><td>Plusieurs milliers d&#39;années</td><td>1 %→10 %</td><td>0,01 %→1 %</td><td>10→30</td></tr><tr><td>Période d&#39;Établissement du Système Symbiotique</td><td>Plusieurs centaines d&#39;années</td><td>10 %→40 %</td><td>1 %→10 %</td><td>30→50</td></tr><tr><td>Ère de l&#39;Ouverture et de l&#39;Activation des Systèmes</td><td>Plusieurs centaines d&#39;années</td><td>40 %→70 %</td><td>10 %→30 %</td><td>50→70</td></tr><tr><td>Ère de la Première Ascension</td><td>Plusieurs décennies</td><td>70 %→85 %</td><td>30 %→50 %</td><td>70→80</td></tr><tr><td>Ère de la République des Dix Mille Races</td><td>Plusieurs centaines d&#39;années</td><td>85 %→95 %</td><td>50 %→70 %</td><td>80→90</td></tr><tr><td>Ère de l&#39;Exploration Interplans</td><td>Plusieurs milliers d&#39;années</td><td>95 %→99 %</td><td>70 %→90 %</td><td>90→95</td></tr><tr><td>Ère de la Symbiose Interstellaire</td><td>En cours</td><td>→100 %</td><td>→100 %</td><td>→100</td></tr></tbody></table><p>La couverture de l&#39;Ancre désigne la proportion de sous-régions de plans où le matériel de l&#39;Ancre a été déployé ; la proportion de cultivateurs désigne la proportion de formes de vie couvertes par les systèmes de culture formels ; l&#39;Indice de Symbiose est un indicateur global mesurant le degré de symbiose de la civilisation, avec un score maximal de 100.</p><h2 id="iv-la-logique-interne-de-l-evolution-des-eres" tabindex="-1">IV. La Logique Interne de l&#39;Évolution des Ères <a class="header-anchor" href="#iv-la-logique-interne-de-l-evolution-des-eres" aria-label="Permalink to &quot;IV. La Logique Interne de l&#39;Évolution des Ères&quot;">​</a></h2><p>L&#39;évolution des ères de l&#39;Univers Hengyuan n&#39;est pas un écoulement linéaire du temps, mais un processus évolutif en spirale ascendante. Chaque ère résout les contradictions centrales laissées par l&#39;ère précédente tout en nourrissant les conditions de développement de la suivante :</p><ul><li>La contradiction fondamentale de l&#39;Ère Pré-Ancre était la contradiction entre la prédation et la symbiose, dont l&#39;extrême développement a conduit à la nécessité de l&#39;éveil de l&#39;Ancre.</li><li>L&#39;Ère de l&#39;Éveil de l&#39;Ancre a résolu la question de « l&#39;existence des Ancres », mais a fait face au défi institutionnel de « qui les Ancres servent-elles ».</li><li>La Période d&#39;Établissement du Système Symbiotique a achevé la construction institutionnelle, mais le monopole des ressources de culture restreignait encore l&#39;évolution des masses.</li><li>L&#39;Ère de l&#39;Ouverture et de l&#39;Activation des Systèmes a brisé le monopole de la culture, mais le bond des capacités individuelles a apporté de nouveaux défis éthiques et de sécurité.</li><li>L&#39;Ère de la Première Ascension a vérifié la faisabilité de l&#39;ascension, mais l&#39;ascension d&#39;un seul plan était insuffisante pour conduire l&#39;évolution globale de l&#39;univers.</li><li>L&#39;Ère de la République des Dix Mille Races a unifié les institutions de la civilisation, mais l&#39;univers contenait encore une vaste quantité de plans et de races non contactés.</li><li>L&#39;Ère de l&#39;Exploration Interplans a élargi les frontières de la civilisation, mais les plans dispersés nécessitaient des connexions interstellaires plus étroites.</li><li>L&#39;Ère de la Symbiose Interstellaire pointe finalement vers l&#39;objectif ultime de l&#39;ascension globale de l&#39;univers.</li></ul><h2 id="v-positionnement-de-l-ere-actuelle" tabindex="-1">V. Positionnement de l&#39;Ère Actuelle <a class="header-anchor" href="#v-positionnement-de-l-ere-actuelle" aria-label="Permalink to &quot;V. Positionnement de l&#39;Ère Actuelle&quot;">​</a></h2><p>Selon l&#39;état de développement actuel de l&#39;Univers Hengyuan, la civilisation se trouve au point charnière de la transition de la Troisième ère (Période d&#39;Établissement du Système Symbiotique) à la Quatrième ère (Ère de l&#39;Ouverture et de l&#39;Activation des Systèmes). Les institutions symbiotiques ont été mises en œuvre dans les plans principaux, l&#39;ouverture des Trois Cents Systèmes est en cours d&#39;avancement global, et la Stratégie d&#39;Activation de 20 % est entrée dans sa phase de mise en œuvre. Plusieurs technologies clés de la couche d&#39;ingénierie des lois (le Moteur de Déduction du Fruit de Multiplication, les dispositifs de régulation des principes juridiques spatiaux et le Système du Miroir de Réplication) sont passées du laboratoire à la production de masse.</p><p>La tâche centrale de cette période de transition est : garantir que l&#39;ouverture des Trois Cents Systèmes profite véritablement à toutes les formes de vie, tout en cultivant le premier groupe de Puissances Suprêmes du Plan par la Stratégie d&#39;Activation de 20 %, accumulant suffisamment d&#39;énergie et d&#39;expérience pour la première ascension.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Le Tableau Maître de la Division des Ères est le cadre macro de compréhension de l&#39;évolution historique de l&#39;Univers Hengyuan. Il condense la longue histoire de l&#39;univers en huit ères à la logique interne claire, chaque ère étant une étape nécessaire vers l&#39;ascension globale de l&#39;univers. Les documents suivants développeront en détail chaque ère et les grands événements qui s&#39;y trouvent.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>71-前锚点时代 (L&#39;Ère Pré-Ancre)</li><li>72-锚点觉醒纪元 (L&#39;Ère de l&#39;Éveil de l&#39;Ancre)</li><li>76-首次升维里程碑 (Le Jalon de la Première Ascension)</li></ul>',22)])])}const v=t(d,[["render",r]]);export{p as __pageData,v as default};
